  -- Classification and organization (16)
  ($q$Classification of Living Things$q$, $q$Why are organisms classified into groups?$q$, $q${"A":"To organize similarities and relationships","B":"To change their genes","C":"To make every organism identical","D":"To remove names"}$q$::jsonb, $q$A$q$, $q$Classification organizes biological diversity using shared characteristics and ancestry.$q$),
  ($q$Classification of Living Things$q$, $q$Two organisms belong to the same genus. What does this imply?$q$, $q${"A":"They must be the same species","B":"They are more closely related than organisms sharing only a family","C":"They have identical DNA","D":"They must live together"}$q$::jsonb, $q$B$q$, $q$Genus is a narrower grouping than family, indicating closer relationship.$q$),
  ($q$Classification of Living Things$q$, $q$Which feature separates most plants from animals in basic classification?$q$, $q${"A":"Plants always move faster","B":"Animals have cell walls","C":"Plants usually make food by photosynthesis","D":"Animals have chloroplasts"}$q$::jsonb, $q$C$q$, $q$Most plants are autotrophic with chloroplasts, unlike animals.$q$),
  ($q$Classification of Living Things$q$, $q$A mushroom absorbs nutrients from dead matter. Why is it not classified as a green plant?$q$, $q${"A":"It has no cells","B":"It is always unicellular","C":"It produces seeds","D":"It lacks chlorophyll and obtains food externally"}$q$::jsonb, $q$D$q$, $q$Fungi feed by absorption and do not photosynthesize like green plants.$q$),
  ($q$Classification of Living Things$q$, $q$What is the value of a two-part scientific name?$q$, $q${"A":"It identifies genus and species consistently across languages","B":"It gives the animal's age","C":"It lists every ancestor","D":"It gives the exact population size"}$q$::jsonb, $q$A$q$, $q$Binomial names use a standardized genus and species designation.$q$),
  ($q$Classification of Living Things$q$, $q$Why are viruses difficult to place among cellular kingdoms?$q$, $q${"A":"They have many nuclei","B":"They are acellular and reproduce only inside host cells","C":"They are all visible to the naked eye","D":"They photosynthesize"}$q$::jsonb, $q$B$q$, $q$Viruses lack cellular organization and rely on a host to replicate.$q$),
  ($q$Classification of Living Things$q$, $q$Which trait is shared by all living cells?$q$, $q${"A":"A cellulose wall","B":"Chloroplasts","C":"A plasma membrane","D":"A large central vacuole"}$q$::jsonb, $q$C$q$, $q$Every cell has a membrane controlling exchange with its surroundings.$q$),
  ($q$Classification of Living Things$q$, $q$Why does evidence from DNA help classification?$q$, $q${"A":"DNA never changes","B":"Appearance is always meaningless","C":"All organisms have identical genes","D":"Sequence similarities can reveal common ancestry"}$q$::jsonb, $q$D$q$, $q$Inherited sequences provide evidence of evolutionary relationships.$q$),
  ($q$Organization of Life$q$, $q$Several muscle cells work together to contract. What level of organization do they form?$q$, $q${"A":"A tissue","B":"An organ system","C":"A population","D":"An ecosystem"}$q$::jsonb, $q$A$q$, $q$A tissue is a group of similar cells performing a common function.$q$),
  ($q$Organization of Life$q$, $q$The heart contains different tissues working together. What is it?$q$, $q${"A":"A cell","B":"An organ","C":"A species","D":"A colony"}$q$::jsonb, $q$B$q$, $q$An organ combines tissues to perform a particular function.$q$),
  ($q$Organization of Life$q$, $q$Why do large multicellular animals need organ systems?$q$, $q${"A":"Every cell touches the environment","B":"They contain no specialized cells","C":"Different functions require coordinated specialized organs","D":"They have no transport needs"}$q$::jsonb, $q$C$q$, $q$Specialized systems coordinate nutrition, transport and waste removal across a large body.$q$),
  ($q$Organization of Life$q$, $q$Amoeba survives as one cell. What does this show?$q$, $q${"A":"Cells cannot reproduce","B":"Only animals are living","C":"Amoeba has organs","D":"One cell can perform all essential life processes"}$q$::jsonb, $q$D$q$, $q$Its single cell carries out feeding, movement, excretion and reproduction.$q$),
  ($q$Organization of Life$q$, $q$How does division of labour benefit a multicellular organism?$q$, $q${"A":"Specialized cells perform tasks efficiently","B":"It removes the need for energy","C":"All cells become identical","D":"It stops communication"}$q$::jsonb, $q$A$q$, $q$Cell specialization allows efficient performance of different functions.$q$),
  ($q$Organization of Life$q$, $q$Which order moves from smaller to larger biological organization?$q$, $q${"A":"Organ, cell, tissue, system","B":"Cell, tissue, organ, system","C":"System, organ, tissue, cell","D":"Tissue, system, cell, organ"}$q$::jsonb, $q$B$q$, $q$Cells form tissues; tissues form organs; organs work in systems.$q$),
  ($q$Organization of Life$q$, $q$Why is a circulatory system more than just a collection of blood cells?$q$, $q${"A":"It contains no organs","B":"Only blood counts as tissue","C":"Heart, vessels and blood act together in transport","D":"Its parts cannot interact"}$q$::jsonb, $q$C$q$, $q$A system integrates several organs and tissues to perform a shared function.$q$),
  ($q$Organization of Life$q$, $q$Volvox consists of cells associated in a coordinated group. Which form best describes it?$q$, $q${"A":"A single mineral","B":"A filament only","C":"An animal organ","D":"A colony"}$q$::jsonb, $q$D$q$, $q$Volvox is a colonial green alga whose cells cooperate in a spherical group.$q$),
  -- Cell structure (8)
  ($q$Cell Structure and Function$q$, $q$Which organelle releases usable energy from aerobic respiration?$q$, $q${"A":"Mitochondrion","B":"Cell wall","C":"Ribosome","D":"Chloroplast only"}$q$::jsonb, $q$A$q$, $q$Mitochondria are major sites of aerobic ATP production.$q$),
  ($q$Cell Structure and Function$q$, $q$Why do leaf cells contain chloroplasts?$q$, $q${"A":"To digest proteins","B":"To absorb light for photosynthesis","C":"To pump blood","D":"To make cell walls disappear"}$q$::jsonb, $q$B$q$, $q$Chlorophyll within chloroplasts captures light energy used to make sugars.$q$),
  ($q$Cell Structure and Function$q$, $q$What is the main role of ribosomes?$q$, $q${"A":"Water storage","B":"Lipid digestion only","C":"Protein synthesis","D":"Moving chromosomes between organisms"}$q$::jsonb, $q$C$q$, $q$Ribosomes translate messenger RNA into protein chains.$q$),
  ($q$Cell Structure and Function$q$, $q$A plant cell remains firm after taking up water partly because of what structure?$q$, $q${"A":"A nucleus without DNA","B":"A flagellum","C":"Only a cell membrane","D":"A strong cellulose cell wall"}$q$::jsonb, $q$D$q$, $q$The wall resists swelling and supports turgor.$q$),
  ($q$Cell Structure and Function$q$, $q$Which structure controls most movement of substances into and out of a cell?$q$, $q${"A":"Plasma membrane","B":"Nucleolus","C":"Chromosome","D":"Cell wall only"}$q$::jsonb, $q$A$q$, $q$The selectively permeable membrane regulates exchange.$q$),
  ($q$Cell Structure and Function$q$, $q$Why does a mature animal red blood cell lack a nucleus?$q$, $q${"A":"It has never had DNA","B":"More internal space can carry haemoglobin","C":"It performs photosynthesis","D":"It becomes a bacterium"}$q$::jsonb, $q$B$q$, $q$Losing the nucleus creates more room for oxygen-carrying haemoglobin.$q$),
  ($q$Cell Structure and Function$q$, $q$Which structure is found in plant cells but not typical animal cells?$q$, $q${"A":"Cytoplasm","B":"Cell membrane","C":"Cellulose wall","D":"Mitochondrion"}$q$::jsonb, $q$C$q$, $q$Plant cells generally have a cellulose wall; animal cells do not.$q$),
  ($q$Cell Structure and Function$q$, $q$What is the nucleus's main role in a eukaryotic cell?$q$, $q${"A":"Directly pumping blood","B":"Making all food","C":"Producing sunlight","D":"Housing genetic instructions and controlling activities"}$q$::jsonb, $q$D$q$, $q$The nucleus contains DNA, which directs protein production and cell functions.$q$),
  -- Cell and environment (8)
  ($q$Movement Across Cell Membranes$q$, $q$A scent spreads from a crowded room into a corridor. What process is this?$q$, $q${"A":"Diffusion down a concentration gradient","B":"Active transport using ATP","C":"Osmosis of air","D":"Photosynthesis"}$q$::jsonb, $q$A$q$, $q$Random motion produces net movement from higher to lower concentration.$q$),
  ($q$Movement Across Cell Membranes$q$, $q$Water moves through a partially permeable membrane from dilute to concentrated solution. What process is this?$q$, $q${"A":"Evaporation","B":"Osmosis","C":"Active transport of solute","D":"Respiration"}$q$::jsonb, $q$B$q$, $q$Osmosis is net water movement toward lower water potential across a selective membrane.$q$),
  ($q$Movement Across Cell Membranes$q$, $q$Why does active transport require energy?$q$, $q${"A":"It always moves water downhill","B":"It occurs only in dead cells","C":"It can move substances against their concentration gradients","D":"It never uses proteins"}$q$::jsonb, $q$C$q$, $q$Pumps use ATP to move material from lower to higher concentration.$q$),
  ($q$Movement Across Cell Membranes$q$, $q$A plant cell is placed in very salty water. What is likely to happen?$q$, $q${"A":"It bursts from water entry","B":"Its chloroplasts become nuclei","C":"It gains unlimited mass","D":"Water leaves and the membrane may pull from the wall"}$q$::jsonb, $q$D$q$, $q$Water leaves by osmosis; strong loss of turgor can cause plasmolysis.$q$),
  ($q$Movement Across Cell Membranes$q$, $q$Why may an animal cell burst in very dilute water?$q$, $q${"A":"Water enters by osmosis and it lacks a rigid cell wall","B":"Water leaves it rapidly","C":"Its genes turn into salt","D":"Diffusion stops"}$q$::jsonb, $q$A$q$, $q$Osmotic entry can swell a membrane-bound animal cell until it ruptures.$q$),
  ($q$Movement Across Cell Membranes$q$, $q$Which process can move oxygen from an air space into a cell without ATP use?$q$, $q${"A":"Active transport","B":"Diffusion","C":"Mitosis","D":"Translocation"}$q$::jsonb, $q$B$q$, $q$Oxygen moves passively down its concentration gradient.$q$),
  ($q$Movement Across Cell Membranes$q$, $q$What happens to net diffusion when concentrations become equal on both sides of a membrane?$q$, $q${"A":"All molecules stop moving","B":"Only ATP can move molecules","C":"There is no net movement, though particles still move","D":"The membrane vanishes"}$q$::jsonb, $q$C$q$, $q$Random motion continues equally in both directions at equilibrium.$q$),
  ($q$Movement Across Cell Membranes$q$, $q$A root hair takes up mineral ions from a lower concentration outside to a higher one inside. What is required?$q$, $q${"A":"Only osmosis","B":"Only passive diffusion","C":"No membrane","D":"Active transport powered by ATP"}$q$::jsonb, $q$D$q$, $q$Movement against a gradient requires energy-dependent carrier proteins.$q$),
  -- Cell metabolism (8)
  ($q$Cell Nutrition and Respiration$q$, $q$What is the main useful energy carrier made during cellular respiration?$q$, $q${"A":"ATP","B":"Cellulose","C":"Chlorophyll","D":"Starch"}$q$::jsonb, $q$A$q$, $q$Respiration transfers energy from food into ATP for cell activities.$q$),
  ($q$Cell Nutrition and Respiration$q$, $q$What are the main products of complete aerobic breakdown of glucose?$q$, $q${"A":"Ethanol and oxygen","B":"Carbon dioxide and water","C":"Lactic acid and sunlight","D":"Protein and starch"}$q$::jsonb, $q$B$q$, $q$Glucose reacts with oxygen, releasing energy and producing CO₂ and H₂O.$q$),
  ($q$Cell Nutrition and Respiration$q$, $q$Why is respiration different from breathing?$q$, $q${"A":"They are synonyms","B":"Respiration occurs only in lungs","C":"Respiration releases energy in cells; breathing moves air","D":"Breathing synthesizes glucose"}$q$::jsonb, $q$C$q$, $q$Cellular respiration is a chemical process, whereas breathing is ventilation.$q$),
  ($q$Cell Nutrition and Respiration$q$, $q$When yeast ferments sugar without oxygen, what products can form?$q$, $q${"A":"Only oxygen","B":"Water and oxygen only","C":"Starch and nitrogen","D":"Ethanol and carbon dioxide"}$q$::jsonb, $q$D$q$, $q$Alcoholic fermentation converts sugar into ethanol, CO₂ and a small ATP yield.$q$),
  ($q$Cell Nutrition and Respiration$q$, $q$Why does a sprinting muscle produce more lactate when oxygen delivery cannot meet demand?$q$, $q${"A":"Anaerobic pathways help maintain ATP production","B":"Muscle cells stop using glucose","C":"Lactate is sunlight","D":"Mitochondria become chloroplasts"}$q$::jsonb, $q$A$q$, $q$Anaerobic glycolysis can supply ATP temporarily when oxygen is insufficient.$q$),
  ($q$Cell Nutrition and Respiration$q$, $q$What raw materials does a green plant use in photosynthesis?$q$, $q${"A":"Glucose and oxygen","B":"Carbon dioxide and water","C":"Protein and nitrogen gas","D":"Ethanol and oxygen"}$q$::jsonb, $q$B$q$, $q$CO₂ and water are converted into sugars using light energy.$q$),
  ($q$Cell Nutrition and Respiration$q$, $q$Why do living plant cells respire at night?$q$, $q${"A":"They only respire in darkness","B":"Photosynthesis releases ATP at night","C":"They still need ATP for maintenance and transport","D":"Darkness turns them into animals"}$q$::jsonb, $q$C$q$, $q$Respiration continues to supply energy even when photosynthesis stops without light.$q$),
  ($q$Cell Nutrition and Respiration$q$, $q$Which process removes metabolic carbon dioxide from a unicellular aquatic organism?$q$, $q${"A":"Only filtration through a kidney","B":"Only sweating","C":"Only seed dispersal","D":"Diffusion across its surface"}$q$::jsonb, $q$D$q$, $q$CO₂ diffuses across the cell boundary down a concentration gradient.$q$),
  -- Growth and reproduction (8)
  ($q$Growth and Cell Reproduction$q$, $q$Why does mitosis support growth in a young plant?$q$, $q${"A":"It produces more genetically similar body cells","B":"It halves every chromosome number","C":"It produces only gametes","D":"It destroys cell membranes"}$q$::jsonb, $q$A$q$, $q$Mitosis increases cell number while generally preserving chromosome number.$q$),
  ($q$Growth and Cell Reproduction$q$, $q$A root bends toward moisture. Which response is this?$q$, $q${"A":"Phototropism","B":"Hydrotropism","C":"Chemotaxis of animals","D":"A reflex arc"}$q$::jsonb, $q$B$q$, $q$Directional growth in response to water is hydrotropism.$q$),
  ($q$Growth and Cell Reproduction$q$, $q$Why can cuttings produce plants like the parent without pollination?$q$, $q${"A":"They have no cells","B":"They contain only pollen","C":"Vegetative propagation is asexual reproduction","D":"They must fuse with gametes"}$q$::jsonb, $q$C$q$, $q$A cutting grows from existing tissues without fusion of gametes.$q$),
  ($q$Growth and Cell Reproduction$q$, $q$What is a major genetic outcome of sexual reproduction?$q$, $q${"A":"All offspring are clones","B":"Every mutation disappears","C":"Each parent contributes no genes","D":"Offspring can have new combinations of parental alleles"}$q$::jsonb, $q$D$q$, $q$Meiosis and fertilization reshuffle inherited genetic material.$q$),
  ($q$Growth and Cell Reproduction$q$, $q$Why is irreversible increase in dry mass a better sign of growth than temporary swelling?$q$, $q${"A":"It reflects production of new material","B":"Swelling always adds new cells","C":"Dry mass measures only water","D":"Growth never uses nutrients"}$q$::jsonb, $q$A$q$, $q$True growth adds organic matter; water swelling may reverse.$q$),
  ($q$Growth and Cell Reproduction$q$, $q$What happens at fertilization?$q$, $q${"A":"Two body cells divide","B":"Male and female gametes fuse","C":"A seed dries out","D":"A leaf loses water"}$q$::jsonb, $q$B$q$, $q$Fusion of gametes combines genetic material to form a zygote.$q$),
  ($q$Growth and Cell Reproduction$q$, $q$Why is meiosis important before sexual reproduction?$q$, $q${"A":"It doubles chromosome number in gametes","B":"It makes every cell identical","C":"It produces haploid gametes","D":"It prevents fertilization"}$q$::jsonb, $q$C$q$, $q$Halving chromosomes in gametes allows normal diploid number to return at fertilization.$q$),
  ($q$Growth and Cell Reproduction$q$, $q$A shoot grows toward light. Why can uneven auxin distribution cause this?$q$, $q${"A":"Auxin stops all growth","B":"The lit side makes more chlorophyll instantly","C":"Roots pull it physically","D":"Cells on the shaded side elongate more"}$q$::jsonb, $q$D$q$, $q$More auxin on the shaded shoot side promotes greater elongation, bending toward light.$q$),
  -- Support (8)
  ($q$Supporting Systems$q$, $q$What is one advantage of an internal skeleton in a large animal?$q$, $q${"A":"It supports body mass and permits movement","B":"It prevents all growth","C":"It eliminates muscles","D":"It replaces circulation"}$q$::jsonb, $q$A$q$, $q$Bones provide support and levers for muscles while growing with the body.$q$),
  ($q$Supporting Systems$q$, $q$Why can a young plant stem remain upright without much wood?$q$, $q${"A":"Its cells lack water","B":"Turgor pressure supports its cells","C":"It contains an animal skeleton","D":"Air replaces cell walls"}$q$::jsonb, $q$B$q$, $q$Water-filled cells press against walls, creating supportive turgidity.$q$),
  ($q$Supporting Systems$q$, $q$What tissue gives flexible support to the human nose and ears?$q$, $q${"A":"Xylem","B":"Chitin","C":"Cartilage","D":"Starch"}$q$::jsonb, $q$C$q$, $q$Cartilage supports and shapes structures while remaining more flexible than bone.$q$),
  ($q$Supporting Systems$q$, $q$Why must a crab shed its exoskeleton as it grows?$q$, $q${"A":"The shell is made of water","B":"The shell has no protective role","C":"The shell grows faster than the crab","D":"A rigid outer skeleton cannot expand continuously"}$q$::jsonb, $q$D$q$, $q$Molting allows a larger exoskeleton to replace the old rigid one.$q$),
  ($q$Supporting Systems$q$, $q$What is the function of a tendon?$q$, $q${"A":"It connects muscle to bone","B":"It connects blood to lymph","C":"It makes chlorophyll","D":"It stores urine"}$q$::jsonb, $q$A$q$, $q$Tendons transmit muscle pull to bones.$q$),
  ($q$Supporting Systems$q$, $q$Why are some joints surrounded by ligaments?$q$, $q${"A":"To make blood cells","B":"To connect and stabilize bones","C":"To produce hormones","D":"To digest carbohydrates"}$q$::jsonb, $q$B$q$, $q$Ligaments link bones and limit excessive joint movement.$q$),
  ($q$Supporting Systems$q$, $q$How does lignin help mature plant stems?$q$, $q${"A":"It increases osmosis alone","B":"It produces seeds","C":"It stiffens cell walls for support","D":"It makes ATP directly"}$q$::jsonb, $q$C$q$, $q$Lignin strengthens walls in tissues such as xylem.$q$),
  ($q$Supporting Systems$q$, $q$Why do antagonistic muscle pairs move a limb?$q$, $q${"A":"Both push bones","B":"Bones contract","C":"Muscles can only extend","D":"One contracts as the other relaxes"}$q$::jsonb, $q$D$q$, $q$Muscles pull but do not push, so opposite actions require paired muscles.$q$),
  -- Animal transport (8)
  ($q$Transport in Animals$q$, $q$Why are capillary walls very thin?$q$, $q${"A":"To shorten diffusion distance between blood and tissues","B":"To prevent all exchange","C":"To make blood flow backward","D":"To contain bones"}$q$::jsonb, $q$A$q$, $q$Thin walls allow rapid exchange of gases, nutrients and waste.$q$),
  ($q$Transport in Animals$q$, $q$What prevents blood from flowing backward in veins?$q$, $q${"A":"Red cells","B":"Valves","C":"Platelets only","D":"Alveoli"}$q$::jsonb, $q$B$q$, $q$Venous valves stop reversal of low-pressure blood flow.$q$),
  ($q$Transport in Animals$q$, $q$Which blood component mainly carries oxygen?$q$, $q${"A":"Plasma proteins only","B":"Platelets","C":"Red cells containing haemoglobin","D":"White cells"}$q$::jsonb, $q$C$q$, $q$Haemoglobin in red blood cells binds and carries oxygen.$q$),
  ($q$Transport in Animals$q$, $q$Why is the left ventricle wall thicker than the right?$q$, $q${"A":"It stores more food","B":"It has no valves","C":"It receives air directly","D":"It pumps blood through the systemic circulation at higher pressure"}$q$::jsonb, $q$D$q$, $q$Pumping to the whole body requires greater force than pumping to nearby lungs.$q$),
  ($q$Transport in Animals$q$, $q$Which vessels carry blood away from the heart?$q$, $q${"A":"Arteries","B":"Veins","C":"Capillaries only","D":"Lymph vessels only"}$q$::jsonb, $q$A$q$, $q$Arteries conduct blood away from the heart, regardless of oxygen content.$q$),
  ($q$Transport in Animals$q$, $q$Why do platelets matter when skin is cut?$q$, $q${"A":"They transport oxygen","B":"They help blood clot","C":"They produce insulin","D":"They digest bacteria"}$q$::jsonb, $q$B$q$, $q$Platelets help start clot formation and limit blood loss.$q$),
  ($q$Transport in Animals$q$, $q$What is one role of lymph?$q$, $q${"A":"It pumps the heart","B":"It produces carbon dioxide only","C":"It returns tissue fluid to the bloodstream","D":"It replaces all red blood cells"}$q$::jsonb, $q$C$q$, $q$Lymphatic vessels collect excess tissue fluid and return it to circulation.$q$),
  ($q$Transport in Animals$q$, $q$Why does blood pass through lungs before returning to the left side of the heart?$q$, $q${"A":"To absorb glucose from food","B":"To create bone marrow","C":"To remove all plasma","D":"To release CO₂ and take up O₂"}$q$::jsonb, $q$D$q$, $q$Pulmonary exchange oxygenates blood and removes carbon dioxide.$q$),
  -- Plant transport (8)
  ($q$Transport in Plants$q$, $q$What does xylem chiefly transport?$q$, $q${"A":"Water and mineral ions","B":"Only sucrose","C":"Only oxygen gas","D":"Only proteins"}$q$::jsonb, $q$A$q$, $q$Xylem carries water and dissolved minerals from roots toward shoots.$q$),
  ($q$Transport in Plants$q$, $q$What does phloem chiefly transport?$q$, $q${"A":"Only water vapor","B":"Sugars and other organic solutes","C":"Only mineral ions upward","D":"Only carbon dioxide"}$q$::jsonb, $q$B$q$, $q$Phloem translocates products of photosynthesis between sources and sinks.$q$),
  ($q$Transport in Plants$q$, $q$Why are root hairs effective at water uptake?$q$, $q${"A":"They contain lungs","B":"They prevent all osmosis","C":"They provide a large surface area in contact with soil","D":"They make seeds"}$q$::jsonb, $q$C$q$, $q$Their numerous narrow extensions increase contact with soil water.$q$),
  ($q$Transport in Plants$q$, $q$What creates much of the upward pull on xylem water in a leafy plant?$q$, $q${"A":"Sugars pushing it down","B":"The roots making blood pressure","C":"Water boiling in leaves","D":"Transpiration from leaves"}$q$::jsonb, $q$D$q$, $q$Evaporation at leaf surfaces creates tension in the continuous water column.$q$),
  ($q$Transport in Plants$q$, $q$What happens to transpiration when stomata close under dry conditions?$q$, $q${"A":"It usually decreases","B":"It always becomes infinite","C":"It produces more carbon dioxide","D":"It changes xylem into phloem"}$q$::jsonb, $q$A$q$, $q$Closed stomata reduce water-vapour diffusion from leaves.$q$),
  ($q$Transport in Plants$q$, $q$Why can phloem move food both upward and downward in different parts of a plant?$q$, $q${"A":"It has no living cells","B":"Movement follows source-to-sink demand, not a fixed vertical direction","C":"Gravity is absent in plants","D":"It transports only water"}$q$::jsonb, $q$B$q$, $q$Sugars move from producing or storage tissues to growing or consuming tissues.$q$),
  ($q$Transport in Plants$q$, $q$A plant in moving dry air loses water faster. Why?$q$, $q${"A":"Air has no water vapour","B":"The leaf stops photosynthesis instantly","C":"Air movement removes moist air near the leaf","D":"Xylem turns into a gas"}$q$::jsonb, $q$C$q$, $q$Wind maintains a steep water-vapour gradient at the leaf surface.$q$),
  ($q$Transport in Plants$q$, $q$Why do xylem vessels have thick lignified walls?$q$, $q${"A":"To produce gametes","B":"To store food only","C":"To make hormones","D":"To resist collapse under tension and support the plant"}$q$::jsonb, $q$D$q$, $q$Lignin reinforces water-conducting walls under transpiration pull.$q$),
  -- Gas exchange and excretion (8)
  ($q$Gas Exchange and Excretion$q$, $q$Why are lung alveoli numerous and thin-walled?$q$, $q${"A":"They increase surface area and shorten diffusion distance","B":"They store food for years","C":"They make blood flow backward","D":"They block oxygen"}$q$::jsonb, $q$A$q$, $q$A large thin exchange surface supports rapid O₂ and CO₂ diffusion.$q$),
  ($q$Gas Exchange and Excretion$q$, $q$When the diaphragm contracts during inhalation, what happens to chest volume?$q$, $q${"A":"It falls","B":"It increases","C":"It becomes zero","D":"It stays fixed"}$q$::jsonb, $q$B$q$, $q$The diaphragm flattens, increasing thoracic volume and lowering lung pressure.$q$),
  ($q$Gas Exchange and Excretion$q$, $q$Why do fish gills exchange gases efficiently in water?$q$, $q${"A":"They have no blood supply","B":"They need no water flow","C":"Their thin surfaces and blood flow maintain diffusion gradients","D":"They manufacture oxygen atoms"}$q$::jsonb, $q$C$q$, $q$Thin gill surfaces and circulation sustain uptake of dissolved oxygen.$q$),
  ($q$Gas Exchange and Excretion$q$, $q$Which process removes metabolic urea from a mammal?$q$, $q${"A":"Photosynthesis","B":"Pollination","C":"Digestion only","D":"Excretion through the kidneys"}$q$::jsonb, $q$D$q$, $q$Kidneys remove urea from blood and pass it into urine.$q$),
  ($q$Gas Exchange and Excretion$q$, $q$Why is removal of CO₂ an excretory process?$q$, $q${"A":"CO₂ is a waste product of respiration","B":"CO₂ is a nutrient made by lungs","C":"CO₂ contains no atoms","D":"Excretion means removal of undigested food only"}$q$::jsonb, $q$A$q$, $q$Excretion removes metabolic wastes, including CO₂ from cellular respiration.$q$),
  ($q$Gas Exchange and Excretion$q$, $q$In a flowering plant, which structures allow much gas exchange through leaves?$q$, $q${"A":"Seeds","B":"Stomata","C":"Xylem pits only","D":"Pollen grains"}$q$::jsonb, $q$B$q$, $q$Stomatal pores allow CO₂, O₂ and water vapour to diffuse.$q$),
  ($q$Gas Exchange and Excretion$q$, $q$Why does breathing become faster during vigorous exercise?$q$, $q${"A":"Cells stop respiring","B":"The lungs make glucose","C":"Oxygen demand and CO₂ production increase","D":"The blood loses all plasma"}$q$::jsonb, $q$C$q$, $q$Higher metabolic rate requires more gas exchange.$q$),
  ($q$Gas Exchange and Excretion$q$, $q$Which waste is removed mainly by a contractile vacuole in freshwater protozoa?$q$, $q${"A":"Only undigested food","B":"Only proteins","C":"Only carbon dioxide","D":"Excess water"}$q$::jsonb, $q$D$q$, $q$Water enters by osmosis and the vacuole expels excess to prevent swelling.$q$),
  -- Homeostasis (8)
  ($q$Homeostasis$q$, $q$What is homeostasis?$q$, $q${"A":"Maintenance of a relatively stable internal environment","B":"Removal of every body cell","C":"Production of only one hormone","D":"A permanent rise in body temperature"}$q$::jsonb, $q$A$q$, $q$Homeostasis regulates internal conditions around suitable ranges.$q$),
  ($q$Homeostasis$q$, $q$Why do humans sweat in hot conditions?$q$, $q${"A":"To gain heat","B":"Evaporation removes heat from skin","C":"To increase blood sugar","D":"To stop circulation"}$q$::jsonb, $q$B$q$, $q$Evaporating sweat uses heat from the body and cools it.$q$),
  ($q$Homeostasis$q$, $q$What do kidneys regulate besides removing urea?$q$, $q${"A":"Only hair colour","B":"Only bone length","C":"Water and dissolved salt balance","D":"The number of lungs"}$q$::jsonb, $q$C$q$, $q$Kidneys adjust urine production to help control body-fluid volume and ion concentrations.$q$),
  ($q$Homeostasis$q$, $q$A person's blood glucose rises after a meal. Which hormone helps cells take up and store glucose?$q$, $q${"A":"Adrenaline","B":"Thyroxine","C":"Glucagon","D":"Insulin"}$q$::jsonb, $q$D$q$, $q$Insulin promotes glucose uptake and storage, lowering blood glucose.$q$),
  ($q$Homeostasis$q$, $q$Why does shivering warm a cold person?$q$, $q${"A":"Rapid muscle contractions generate heat","B":"Skin cells stop respiring","C":"Blood becomes solid","D":"The body produces sunlight"}$q$::jsonb, $q$A$q$, $q$Muscle activity uses ATP and releases heat.$q$),
  ($q$Homeostasis$q$, $q$What is a negative-feedback response?$q$, $q${"A":"A response that always causes harm","B":"A response that opposes a change from a set range","C":"A response without receptors","D":"A response that magnifies deviation indefinitely"}$q$::jsonb, $q$B$q$, $q$Negative feedback counteracts a disturbance to restore internal balance.$q$),
  ($q$Homeostasis$q$, $q$Why might urine become more concentrated when a person drinks little water?$q$, $q${"A":"The kidneys stop filtering blood","B":"The liver turns into a kidney","C":"More water is reabsorbed to conserve body fluid","D":"More water is lost deliberately"}$q$::jsonb, $q$C$q$, $q$Water conservation reduces urine volume while wastes remain dissolved in less water.$q$),
  ($q$Homeostasis$q$, $q$What role does the liver play in blood-glucose regulation?$q$, $q${"A":"It creates insulin itself","B":"It has no energy stores","C":"It pumps blood like the heart","D":"It stores and releases glucose through glycogen metabolism"}$q$::jsonb, $q$D$q$, $q$The liver converts glucose to glycogen and releases glucose when needed.$q$),
  -- Hormones and nerves (8)
  ($q$Coordination and Response$q$, $q$A hand withdraws quickly from a hot object before conscious thought. What type of action is this?$q$, $q${"A":"A reflex","B":"Photosynthesis","C":"Pollination","D":"A learned essay"}$q$::jsonb, $q$A$q$, $q$A reflex arc produces a rapid automatic response to a harmful stimulus.$q$),
  ($q$Coordination and Response$q$, $q$Why are nerve signals often faster than hormonal responses?$q$, $q${"A":"Hormones have no effects","B":"Impulses travel along neurons rather than relying on blood transport","C":"Nerves contain no cells","D":"Hormones always move through xylem"}$q$::jsonb, $q$B$q$, $q$Electrical impulses move rapidly through neural pathways; hormones are carried in blood.$q$),
  ($q$Coordination and Response$q$, $q$Which brain part chiefly coordinates balance and fine movement?$q$, $q${"A":"Medulla","B":"Hypothalamus","C":"Cerebellum","D":"Pituitary gland"}$q$::jsonb, $q$C$q$, $q$The cerebellum helps coordinate posture and smooth movement.$q$),
  ($q$Coordination and Response$q$, $q$Why does adrenaline help prepare a person for sudden danger?$q$, $q${"A":"It stops heart activity","B":"It removes oxygen from blood","C":"It prevents muscle blood flow","D":"It raises heart rate and mobilizes energy"}$q$::jsonb, $q$D$q$, $q$Adrenaline supports rapid physical response by increasing circulation and available fuel.$q$),
  ($q$Coordination and Response$q$, $q$What detects a change in the environment at the start of a reflex arc?$q$, $q${"A":"A receptor","B":"An effector","C":"A red blood cell","D":"A phloem vessel"}$q$::jsonb, $q$A$q$, $q$Receptors sense a stimulus and begin neural signalling.$q$),
  ($q$Coordination and Response$q$, $q$How does a motor neurone contribute to a reflex?$q$, $q${"A":"It detects light in the eye","B":"It carries an impulse to a muscle or gland","C":"It makes antibodies","D":"It carries sugar in plants"}$q$::jsonb, $q$B$q$, $q$Motor neurones conduct signals from the central nervous system to effectors.$q$),
  ($q$Coordination and Response$q$, $q$Which part of the brain is especially involved in conscious thought and memory?$q$, $q${"A":"Cerebellum only","B":"Medulla only","C":"Cerebrum","D":"Spinal cord only"}$q$::jsonb, $q$C$q$, $q$The cerebrum supports higher cognition, memory and voluntary activity.$q$),
  ($q$Coordination and Response$q$, $q$What is the role of a plant growth hormone such as auxin?$q$, $q${"A":"It acts as animal insulin","B":"It pumps sap mechanically","C":"It replaces all mineral ions","D":"It regulates processes including cell elongation"}$q$::jsonb, $q$D$q$, $q$Auxin influences growth patterns, including elongation in shoots.$q$),
  -- Animal reproduction (8)
  ($q$Reproduction in Animals$q$, $q$Where does fertilization usually occur in the human female reproductive system?$q$, $q${"A":"Oviduct","B":"Uterine wall","C":"Vagina","D":"Ovary"}$q$::jsonb, $q$A$q$, $q$Sperm and egg usually fuse in an oviduct before the embryo moves toward the uterus.$q$),
  ($q$Reproduction in Animals$q$, $q$What is the placenta's main role during pregnancy?$q$, $q${"A":"To produce the father's gametes","B":"To exchange nutrients, gases and wastes between maternal and fetal blood","C":"To replace the embryo's DNA","D":"To digest food inside the fetus"}$q$::jsonb, $q$B$q$, $q$The placenta supports exchange while the two blood supplies normally remain separate.$q$),
  ($q$Reproduction in Animals$q$, $q$Why is a mammalian egg larger than a sperm cell?$q$, $q${"A":"It swims farther","B":"It has no genetic material","C":"It contains more cytoplasm and stored resources for early development","D":"It has no membrane"}$q$::jsonb, $q$C$q$, $q$The ovum supplies cytoplasm and early resources; sperm is specialized for delivery of DNA.$q$),
  ($q$Reproduction in Animals$q$, $q$Which feature distinguishes complete insect metamorphosis?$q$, $q${"A":"No change after hatching","B":"Only egg and adult stages","C":"Adult formed directly from egg","D":"A distinct pupal stage between larva and adult"}$q$::jsonb, $q$D$q$, $q$Complete metamorphosis includes egg, larva, pupa and adult.$q$),
  ($q$Reproduction in Animals$q$, $q$Why can internal fertilization help land animals reproduce?$q$, $q${"A":"Gametes are less exposed to drying outside the body","B":"It guarantees every offspring survives","C":"It eliminates gametes","D":"It makes embryos photosynthesize"}$q$::jsonb, $q$A$q$, $q$Internal union protects gametes from the dry external environment.$q$),
  ($q$Reproduction in Animals$q$, $q$What is an immediate result of sperm-egg fusion?$q$, $q${"A":"A placenta","B":"A zygote","C":"A larva","D":"A fully formed fetus"}$q$::jsonb, $q$B$q$, $q$The fertilized egg is the zygote, which then begins cell division.$q$),
  ($q$Reproduction in Animals$q$, $q$What do testes produce?$q$, $q${"A":"Ova and progesterone","B":"Only urine","C":"Sperm and testosterone","D":"Milk and oestrogen"}$q$::jsonb, $q$C$q$, $q$Testes make male gametes and secrete testosterone.$q$),
  ($q$Reproduction in Animals$q$, $q$Why is yolk useful in a developing bird egg?$q$, $q${"A":"It serves only as a shell","B":"It removes oxygen from the egg","C":"It prevents all cell division","D":"It supplies nutrients to the embryo"}$q$::jsonb, $q$D$q$, $q$Yolk is a food reserve supporting development before hatching.$q$),
  -- Plant reproduction (8)
  ($q$Reproduction in Flowering Plants$q$, $q$What does pollination transfer?$q$, $q${"A":"Pollen from anther to stigma","B":"Seeds from fruit to soil","C":"Water from root to leaf","D":"Sugars from leaf to root"}$q$::jsonb, $q$A$q$, $q$Pollination moves pollen to a receptive stigma.$q$),
  ($q$Reproduction in Flowering Plants$q$, $q$Why can cross-pollination increase genetic variation?$q$, $q${"A":"It uses one parent's genes only","B":"It combines gametes from different plants","C":"It stops fertilization","D":"It makes every seed identical"}$q$::jsonb, $q$B$q$, $q$Different parent plants can contribute different allele combinations.$q$),
  ($q$Reproduction in Flowering Plants$q$, $q$What grows from a pollen grain toward an ovule?$q$, $q${"A":"A root hair","B":"An embryo","C":"A pollen tube","D":"A leaf vein"}$q$::jsonb, $q$C$q$, $q$The pollen tube carries male gametes down the style to an ovule.$q$),
  ($q$Reproduction in Flowering Plants$q$, $q$After fertilization, what does an ovule usually become?$q$, $q${"A":"A petal","B":"A stigma","C":"A stem","D":"A seed"}$q$::jsonb, $q$D$q$, $q$The fertilized ovule develops into a seed containing the embryo.$q$),
  ($q$Reproduction in Flowering Plants$q$, $q$Why is wind dispersal useful for a seed?$q$, $q${"A":"It can reduce competition with the parent plant","B":"It ensures every seed germinates","C":"It makes the seed heavier","D":"It removes the embryo"}$q$::jsonb, $q$A$q$, $q$Carrying seeds away spreads offspring to sites with potentially more resources.$q$),
  ($q$Reproduction in Flowering Plants$q$, $q$Which floral part contains the ovules?$q$, $q${"A":"Anther","B":"Ovary","C":"Sepal","D":"Petal"}$q$::jsonb, $q$B$q$, $q$Ovules lie within the ovary of the carpel.$q$),
  ($q$Reproduction in Flowering Plants$q$, $q$A seed fails to germinate in very dry soil despite warmth and oxygen. Which requirement is missing?$q$, $q${"A":"Sunlight always","B":"A pollinator","C":"Water","D":"Chlorophyll in the seed"}$q$::jsonb, $q$C$q$, $q$Water rehydrates tissues and activates metabolism needed for germination.$q$),
  ($q$Reproduction in Flowering Plants$q$, $q$Why can a fruit aid seed dispersal by animals?$q$, $q${"A":"All fruits float","B":"It destroys the seed","C":"It replaces the flower's DNA","D":"It can attract animals that carry or eat the fruit"}$q$::jsonb, $q$D$q$, $q$Fleshy fruit may encourage animals to transport seeds away from the parent.$q$),
  -- Photosynthesis (8)
  ($q$Photosynthesis and Plant Nutrition$q$, $q$What energy source drives photosynthesis?$q$, $q${"A":"Light","B":"Sound","C":"Soil pressure","D":"Moon gravity"}$q$::jsonb, $q$A$q$, $q$Chlorophyll captures light energy for sugar production.$q$),
  ($q$Photosynthesis and Plant Nutrition$q$, $q$Why is carbon dioxide needed by a green plant?$q$, $q${"A":"It provides mineral nitrogen","B":"It supplies carbon for carbohydrate synthesis","C":"It provides sunlight","D":"It replaces water in all cells"}$q$::jsonb, $q$B$q$, $q$Carbon atoms from CO₂ are fixed into organic molecules.$q$),
  ($q$Photosynthesis and Plant Nutrition$q$, $q$What gas is released when water is split during light reactions?$q$, $q${"A":"Nitrogen","B":"Hydrogen chloride","C":"Oxygen","D":"Methane"}$q$::jsonb, $q$C$q$, $q$Splitting water provides electrons and releases O₂.$q$),
  ($q$Photosynthesis and Plant Nutrition$q$, $q$A plant receives enough light and water but very little CO₂. What is likely to limit photosynthesis?$q$, $q${"A":"The number of petals","B":"Only gravity","C":"The shape of roots","D":"Carbon dioxide availability"}$q$::jsonb, $q$D$q$, $q$Low CO₂ restricts carbon fixation even if other factors are sufficient.$q$),
  ($q$Photosynthesis and Plant Nutrition$q$, $q$Why do plants need magnesium ions?$q$, $q${"A":"Magnesium is part of chlorophyll","B":"Magnesium replaces all proteins","C":"It makes roots photosynthesize in darkness","D":"It is the only component of water"}$q$::jsonb, $q$A$q$, $q$Chlorophyll molecules contain a central magnesium ion.$q$),
  ($q$Photosynthesis and Plant Nutrition$q$, $q$What is one fate of glucose made by photosynthesis?$q$, $q${"A":"It must be excreted","B":"It can be converted to starch for storage","C":"It becomes a mineral element","D":"It is never used in respiration"}$q$::jsonb, $q$B$q$, $q$Plants store some glucose as insoluble starch and use some in respiration or growth.$q$),
  ($q$Photosynthesis and Plant Nutrition$q$, $q$Why does leaf chlorophyll appear green?$q$, $q${"A":"It absorbs only green light","B":"It creates green light from nothing","C":"It reflects more green light than many other visible colours","D":"It contains no pigment"}$q$::jsonb, $q$C$q$, $q$Chlorophyll absorbs mainly red and blue wavelengths and reflects much green.$q$),
  ($q$Photosynthesis and Plant Nutrition$q$, $q$What happens to photosynthesis when light intensity rises from very low to moderate while other resources remain ample?$q$, $q${"A":"It must stop","B":"It becomes fermentation","C":"It is unaffected at all levels","D":"Its rate usually increases"}$q$::jsonb, $q$D$q$, $q$More available light supports faster reactions until another factor becomes limiting.$q$),
  -- Animal nutrition (8)
  ($q$Animal Nutrition and Digestion$q$, $q$Why is a balanced diet important?$q$, $q${"A":"It supplies varied nutrients in suitable amounts","B":"It contains only one food type","C":"It eliminates water need","D":"It stops all metabolism"}$q$::jsonb, $q$A$q$, $q$Different nutrients support energy, growth, repair and body regulation.$q$),
  ($q$Animal Nutrition and Digestion$q$, $q$Where does most chemical digestion and absorption occur in humans?$q$, $q${"A":"The oesophagus","B":"The small intestine","C":"The large intestine only","D":"The mouth only"}$q$::jsonb, $q$B$q$, $q$Enzymes complete much digestion in the small intestine, and villi absorb nutrients.$q$),
  ($q$Animal Nutrition and Digestion$q$, $q$Why do intestinal villi improve absorption?$q$, $q${"A":"They produce all red cells","B":"They stop circulation","C":"They greatly increase surface area","D":"They replace enzymes"}$q$::jsonb, $q$C$q$, $q$Many villi and microvilli expose a large absorptive membrane to digested food.$q$),
  ($q$Animal Nutrition and Digestion$q$, $q$What does amylase act on?$q$, $q${"A":"Fat","B":"Protein","C":"Vitamin C","D":"Starch"}$q$::jsonb, $q$D$q$, $q$Amylase breaks starch into smaller sugars.$q$),
  ($q$Animal Nutrition and Digestion$q$, $q$Why is bile useful during fat digestion?$q$, $q${"A":"It emulsifies fat into small droplets","B":"It is the main fat-digesting enzyme","C":"It converts fat to glucose directly","D":"It makes oxygen"}$q$::jsonb, $q$A$q$, $q$Emulsification increases fat surface area for lipase action.$q$),
  ($q$Animal Nutrition and Digestion$q$, $q$Which nutrient class is especially needed to build body proteins?$q$, $q${"A":"Mineral salts only","B":"Dietary protein providing amino acids","C":"Water alone","D":"Cellulose alone"}$q$::jsonb, $q$B$q$, $q$Digested amino acids are used to synthesize body proteins.$q$),
  ($q$Animal Nutrition and Digestion$q$, $q$What is peristalsis?$q$, $q${"A":"Production of bile","B":"Absorption by villi","C":"Wave-like muscle contractions moving food along the gut","D":"Cell division in the stomach"}$q$::jsonb, $q$C$q$, $q$Coordinated gut-wall contractions propel food through the alimentary canal.$q$),
  ($q$Animal Nutrition and Digestion$q$, $q$A child lacks adequate vitamin C for a long period. Which problem may result?$q$, $q${"A":"Rickets from vitamin D deficiency","B":"Night blindness from vitamin A deficiency","C":"Iron overload","D":"Scurvy and impaired connective-tissue maintenance"}$q$::jsonb, $q$D$q$, $q$Vitamin C is needed for collagen formation; deficiency causes scurvy.$q$),
  -- Ecosystems (8)
  ($q$Ecosystem Concepts$q$, $q$Which component of a pond is abiotic?$q$, $q${"A":"Water temperature","B":"Algae","C":"Fish","D":"Bacteria"}$q$::jsonb, $q$A$q$, $q$Temperature is a nonliving physical condition.$q$),
  ($q$Ecosystem Concepts$q$, $q$What is a population in ecology?$q$, $q${"A":"All organisms of all species worldwide","B":"Members of one species in an area at a time","C":"Only nonliving factors","D":"All food chains combined"}$q$::jsonb, $q$B$q$, $q$A population consists of individuals of the same species living in a defined area.$q$),
  ($q$Ecosystem Concepts$q$, $q$Why does a cactus have a thick waxy outer surface?$q$, $q${"A":"To absorb more rain by leaves","B":"To attract fish","C":"To reduce water loss in dry habitat","D":"To increase evaporation"}$q$::jsonb, $q$C$q$, $q$A waxy cuticle limits evaporative loss.$q$),
  ($q$Ecosystem Concepts$q$, $q$Which interaction benefits one organism while harming the other?$q$, $q${"A":"Mutualism","B":"Commensalism","C":"Cooperation","D":"Parasitism"}$q$::jsonb, $q$D$q$, $q$A parasite obtains resources at its host's expense.$q$),
  ($q$Ecosystem Concepts$q$, $q$What is an organism's habitat?$q$, $q${"A":"The place where it lives","B":"Its exact genetic sequence","C":"Its entire food web","D":"Its scientific name"}$q$::jsonb, $q$A$q$, $q$Habitat refers to the physical place or environment an organism occupies.$q$),
  ($q$Ecosystem Concepts$q$, $q$Why might two bird species compete in one forest?$q$, $q${"A":"They always share genes","B":"They use the same limited nesting sites or food","C":"They never interact","D":"They both make soil"}$q$::jsonb, $q$B$q$, $q$Competition arises when organisms need the same limited resources.$q$),
  ($q$Ecosystem Concepts$q$, $q$What is an ecological niche?$q$, $q${"A":"Only a place name","B":"The total number of species","C":"A species' role and resource use in its environment","D":"A type of microscope"}$q$::jsonb, $q$C$q$, $q$Niche includes how an organism uses resources and interacts with others.$q$),
  ($q$Ecosystem Concepts$q$, $q$Why can a wetland support many kinds of organism?$q$, $q${"A":"It has no food chains","B":"It contains no physical gradients","C":"Every organism has identical needs","D":"It provides varied habitats and resources"}$q$::jsonb, $q$D$q$, $q$Differences in water depth, vegetation and food support different species.$q$),
  -- Energy flow and nutrient cycles (8)
  ($q$Energy Flow and Nutrient Cycles$q$, $q$Grass → grasshopper → frog. What role does the grasshopper play?$q$, $q${"A":"Primary consumer","B":"Producer","C":"Decomposer","D":"Tertiary consumer"}$q$::jsonb, $q$A$q$, $q$The grasshopper eats the producer and is the first consumer level.$q$),
  ($q$Energy Flow and Nutrient Cycles$q$, $q$Why does less energy reach higher trophic levels?$q$, $q${"A":"Energy is created at each transfer","B":"Organisms use energy and release much as heat","C":"Producers do not respire","D":"Predators have no metabolism"}$q$::jsonb, $q$B$q$, $q$Respiration and other activities dissipate energy at each transfer.$q$),
  ($q$Energy Flow and Nutrient Cycles$q$, $q$What role do decomposers play in a forest?$q$, $q${"A":"They stop all decay","B":"They make sunlight","C":"They break dead matter and recycle nutrients","D":"They eat only living leaves"}$q$::jsonb, $q$C$q$, $q$Microorganisms release nutrients from dead organisms back into soil and water.$q$),
  ($q$Energy Flow and Nutrient Cycles$q$, $q$Which process removes CO₂ from the atmosphere into biomass?$q$, $q${"A":"Respiration","B":"Combustion","C":"Decomposition only","D":"Photosynthesis"}$q$::jsonb, $q$D$q$, $q$Photosynthetic organisms fix atmospheric carbon into organic compounds.$q$),
  ($q$Energy Flow and Nutrient Cycles$q$, $q$Why are legumes valuable in a crop rotation?$q$, $q${"A":"Root bacteria can fix nitrogen into usable compounds","B":"They remove all soil nitrogen","C":"They prevent photosynthesis","D":"They turn water into phosphorus"}$q$::jsonb, $q$A$q$, $q$Symbiotic bacteria in many legumes add biologically available nitrogen to the system.$q$),
  ($q$Energy Flow and Nutrient Cycles$q$, $q$What do arrows in a food chain indicate when written as grass → goat → human?$q$, $q${"A":"Direction animals run","B":"Direction of energy transfer through feeding","C":"Only size of organisms","D":"Direction of rainfall"}$q$::jsonb, $q$B$q$, $q$Arrows point from food to consumer, tracing energy flow.$q$),
  ($q$Energy Flow and Nutrient Cycles$q$, $q$Why can nutrients cycle while energy flows one way through an ecosystem?$q$, $q${"A":"Nutrients are always destroyed","B":"Sunlight is recycled by roots","C":"Matter is reused, but energy dissipates as heat","D":"Decomposers create all energy"}$q$::jsonb, $q$C$q$, $q$Chemical elements return through biogeochemical cycles; energy eventually leaves as heat.$q$),
  ($q$Energy Flow and Nutrient Cycles$q$, $q$Which organism starts a typical grazing food chain?$q$, $q${"A":"Carnivore","B":"Parasite","C":"Decomposer","D":"Green producer"}$q$::jsonb, $q$D$q$, $q$Photosynthetic producers capture light energy and build the initial food supply.$q$),
  -- Population ecology (8)
  ($q$Population Ecology$q$, $q$A population gains more individuals through births than it loses through deaths, with no migration. What happens?$q$, $q${"A":"It grows","B":"It must disappear","C":"It stays exactly constant","D":"Its species changes instantly"}$q$::jsonb, $q$A$q$, $q$Positive natural increase adds individuals when births exceed deaths.$q$),
  ($q$Population Ecology$q$, $q$What is immigration in population ecology?$q$, $q${"A":"Individuals leaving an area","B":"Individuals entering an area","C":"Individuals dying","D":"Individuals being born"}$q$::jsonb, $q$B$q$, $q$Immigration adds members arriving from elsewhere.$q$),
  ($q$Population Ecology$q$, $q$Why can food shortage slow population growth?$q$, $q${"A":"It guarantees more births","B":"It removes all predators","C":"Survival and reproduction may decline","D":"It increases habitat space"}$q$::jsonb, $q$C$q$, $q$Limited food is a density-dependent constraint on survival and breeding.$q$),
  ($q$Population Ecology$q$, $q$What usually begins primary succession on bare rock?$q$, $q${"A":"A mature forest immediately","B":"Large grazing mammals","C":"A cultivated field","D":"Pioneer organisms able to colonize exposed surface"}$q$::jsonb, $q$D$q$, $q$Hardy pioneers such as lichens can establish before soil forms.$q$),
  ($q$Population Ecology$q$, $q$A forest regrows after a fire while soil remains. Which succession is this?$q$, $q${"A":"Secondary succession","B":"Primary succession on bare rock","C":"No succession","D":"Artificial selection"}$q$::jsonb, $q$A$q$, $q$Secondary succession follows disturbance where soil and some biological material remain.$q$),
  ($q$Population Ecology$q$, $q$What is carrying capacity?$q$, $q${"A":"Total mass of one animal","B":"Population size an environment can sustain over time","C":"Number of predators only","D":"Maximum rainfall in a day"}$q$::jsonb, $q$B$q$, $q$Resources and conditions limit the population that can persist.$q$),
  ($q$Population Ecology$q$, $q$Why can a new predator reduce a prey population?$q$, $q${"A":"Predators always increase births","B":"Prey become plants","C":"Predation raises prey mortality","D":"Food supply becomes unlimited"}$q$::jsonb, $q$C$q$, $q$More prey are removed when predation pressure rises.$q$),
  ($q$Population Ecology$q$, $q$If 20 organisms leave a population while all other changes are zero, what happens to population size?$q$, $q${"A":"It rises by 20","B":"It doubles","C":"It is unchanged","D":"It falls by 20"}$q$::jsonb, $q$D$q$, $q$Emigration subtracts individuals from the local population.$q$),
  -- Pollution and conservation (8)
  ($q$Pollution and Conservation$q$, $q$Why can fertilizer runoff cause fish deaths in a lake?$q$, $q${"A":"Nutrient enrichment can trigger blooms whose decay depletes oxygen","B":"Fertilizer removes all water","C":"Fish cannot live near plants","D":"The lake instantly freezes"}$q$::jsonb, $q$A$q$, $q$Eutrophication leads to microbial decomposition that consumes dissolved oxygen.$q$),
  ($q$Pollution and Conservation$q$, $q$What can help prevent soil erosion on a steep cultivated slope?$q$, $q${"A":"Removing all vegetation","B":"Maintaining plant cover and contour farming","C":"Burning all roots","D":"Increasing bare exposed soil"}$q$::jsonb, $q$B$q$, $q$Roots hold soil and contouring slows runoff.$q$),
  ($q$Pollution and Conservation$q$, $q$Why is protecting a forest habitat more effective than saving just one tree species?$q$, $q${"A":"Forests contain only trees","B":"Species never interact","C":"It preserves interconnected species and ecosystem processes","D":"It prevents all natural change"}$q$::jsonb, $q$C$q$, $q$Habitat conservation supports communities, food webs and ecological functions.$q$),
  ($q$Pollution and Conservation$q$, $q$How can untreated sewage threaten a community's drinking water?$q$, $q${"A":"It always sterilizes water","B":"It removes all microbes","C":"It adds only harmless minerals","D":"It may introduce disease-causing microorganisms"}$q$::jsonb, $q$D$q$, $q$Sewage can carry pathogens into water sources.$q$),
  ($q$Pollution and Conservation$q$, $q$Why are protected wildlife areas useful?$q$, $q${"A":"They conserve breeding habitat and biodiversity","B":"They eliminate every human need","C":"They make hunting unlimited","D":"They stop evolution"}$q$::jsonb, $q$A$q$, $q$Protected habitat can support populations and ecological interactions.$q$),
  ($q$Pollution and Conservation$q$, $q$What is a likely effect of excessive pesticide use?$q$, $q${"A":"Only target pests are affected","B":"Non-target organisms and food webs may be harmed","C":"All soil becomes more fertile","D":"Resistance is impossible"}$q$::jsonb, $q$B$q$, $q$Pesticides can affect beneficial species and accumulate through ecological interactions.$q$),
  ($q$Pollution and Conservation$q$, $q$Why can planting native trees help a damaged watershed?$q$, $q${"A":"It stops rainfall","B":"It removes all soil organisms","C":"Roots stabilize soil and vegetation regulates runoff","D":"It makes rivers evaporate"}$q$::jsonb, $q$C$q$, $q$Plant cover reduces erosion and can improve water retention.$q$),
  ($q$Pollution and Conservation$q$, $q$Why should water resources be managed across an entire drainage basin?$q$, $q${"A":"Upstream actions never affect downstream users","B":"Only rainfall matters","C":"Rivers have no connected tributaries","D":"Pollution and withdrawals upstream affect downstream communities"}$q$::jsonb, $q$D$q$, $q$Watersheds are connected; management must account for impacts across locations.$q$),
  -- Microorganisms and public health (8)
  ($q$Microorganisms and Public Health$q$, $q$Why must drinking water be protected from human sewage?$q$, $q${"A":"Sewage may carry disease-causing microbes","B":"Sewage always improves taste","C":"Water cannot carry pathogens","D":"Boiling creates bacteria"}$q$::jsonb, $q$A$q$, $q$Faecal contamination can transmit intestinal pathogens through water.$q$),
  ($q$Microorganisms and Public Health$q$, $q$How does vaccination reduce infectious disease?$q$, $q${"A":"It removes every microbe from the environment","B":"It trains immune memory against a pathogen","C":"It replaces nutrition","D":"It makes antibiotics unnecessary for all illness"}$q$::jsonb, $q$B$q$, $q$Vaccination exposes the immune system to a safe antigenic stimulus, building protective memory.$q$),
  ($q$Microorganisms and Public Health$q$, $q$Why do antibiotics not treat a viral cold directly?$q$, $q${"A":"Viruses have bacterial cell walls","B":"Colds contain no particles","C":"Antibiotics target bacterial processes absent from viruses","D":"Antibiotics are nutrients"}$q$::jsonb, $q$C$q$, $q$Viruses lack the bacterial structures or metabolism many antibiotics act on.$q$),
  ($q$Microorganisms and Public Health$q$, $q$Which organism transmits malaria parasites between humans?$q$, $q${"A":"Housefly","B":"Tick","C":"Honeybee","D":"Female Anopheles mosquito"}$q$::jsonb, $q$D$q$, $q$Infected female Anopheles mosquitoes transmit Plasmodium during blood feeding.$q$),
  ($q$Microorganisms and Public Health$q$, $q$Why does proper food preservation slow spoilage?$q$, $q${"A":"It reduces conditions needed for microbial growth","B":"It removes all nutrients from food","C":"It always makes food sterile forever","D":"It changes all microbes into minerals"}$q$::jsonb, $q$A$q$, $q$Low temperature, drying or other methods can limit microbial multiplication.$q$),
  ($q$Microorganisms and Public Health$q$, $q$What is the role of decomposing microbes in soil?$q$, $q${"A":"They stop nutrient cycles","B":"They break down organic remains and release nutrients","C":"They turn soil into plastic","D":"They prevent all plant growth"}$q$::jsonb, $q$B$q$, $q$Decomposition returns mineral nutrients from dead matter to the ecosystem.$q$),
  ($q$Microorganisms and Public Health$q$, $q$Why should a person complete an appropriately prescribed antibiotic course as directed?$q$, $q${"A":"Antibiotics work only after a year","B":"It guarantees no side effects","C":"Incorrect use can leave infection inadequately treated and select resistance","D":"It turns viruses into bacteria"}$q$::jsonb, $q$C$q$, $q$Following clinical directions helps treat susceptible infection and limits misuse.$q$),
  ($q$Microorganisms and Public Health$q$, $q$How does handwashing with soap reduce disease transmission?$q$, $q${"A":"It changes human genes","B":"It replaces vaccination","C":"It makes skin impermeable","D":"It removes many microbes before they reach mouths or surfaces"}$q$::jsonb, $q$D$q$, $q$Soap and rubbing dislodge pathogens, lowering transfer between people.$q$),
  -- Genetics and variation (8)
  ($q$Genetics and Variation$q$, $q$A child receives one allele from each parent for a gene. What process makes this possible?$q$, $q${"A":"Formation and fusion of gametes","B":"Only diffusion","C":"Only digestion","D":"Only transpiration"}$q$::jsonb, $q$A$q$, $q$Meiosis forms gametes carrying one allele; fertilization brings parental alleles together.$q$),
  ($q$Genetics and Variation$q$, $q$If T is dominant for tallness and t recessive, what is the phenotype of Tt?$q$, $q${"A":"Short","B":"Tall","C":"Neither tall nor short necessarily","D":"Always sterile"}$q$::jsonb, $q$B$q$, $q$The dominant T allele is expressed in the heterozygote.$q$),
  ($q$Genetics and Variation$q$, $q$Two heterozygous parents are Tt × Tt. What fraction of offspring is expected to be tt in a simple single-gene model?$q$, $q${"A":"1/2","B":"3/4","C":"1/4","D":"All"}$q$::jsonb, $q$C$q$, $q$Each parent gives t with probability 1/2, so tt probability is 1/2 × 1/2 = 1/4.$q$),
  ($q$Genetics and Variation$q$, $q$What is a genotype?$q$, $q${"A":"Only visible height","B":"Only an organism's habitat","C":"The number of food chains","D":"An organism's allelic makeup for a trait"}$q$::jsonb, $q$D$q$, $q$Genotype describes inherited allele combinations, such as Tt.$q$),
  ($q$Genetics and Variation$q$, $q$Why can siblings differ despite having the same parents?$q$, $q${"A":"Meiosis and fertilization create different allele combinations","B":"Parents transmit identical gametes every time","C":"Environment never affects traits","D":"Every child is a clone"}$q$::jsonb, $q$A$q$, $q$Independent assortment, recombination and random gamete fusion produce variation.$q$),
  ($q$Genetics and Variation$q$, $q$What determines biological sex in the usual human XX/XY system at conception?$q$, $q${"A":"The mother's egg carrying X or Y","B":"Whether the fertilizing sperm carries X or Y","C":"The number of red cells","D":"Only body temperature"}$q$::jsonb, $q$B$q$, $q$Human eggs carry X; a sperm may contribute X or Y.$q$),
  ($q$Genetics and Variation$q$, $q$Why may a recessive trait reappear after being absent in one generation?$q$, $q${"A":"Dominant alleles disappear in every child","B":"Genes are made by diet alone","C":"Unaffected carriers can each pass on a recessive allele","D":"Meiosis never shuffles alleles"}$q$::jsonb, $q$C$q$, $q$Heterozygous carriers may lack the phenotype but can produce a homozygous recessive child.$q$),
  ($q$Genetics and Variation$q$, $q$Why is a chromosome important in heredity?$q$, $q${"A":"It is only a food reserve","B":"It makes antibodies only","C":"It carries no information","D":"It contains DNA with many genes"}$q$::jsonb, $q$D$q$, $q$Chromosomes package genetic information transmitted through cell division and reproduction.$q$),
  -- Evolution (8)
  ($q$Evolution$q$, $q$Why can antibiotic resistance spread through a bacterial population?$q$, $q${"A":"Resistant bacteria survive treatment and reproduce","B":"Antibiotics teach all bacteria the same gene","C":"Resistance always reduces survival","D":"Bacteria cannot vary"}$q$::jsonb, $q$A$q$, $q$Selection increases the frequency of variants that survive exposure.$q$),
  ($q$Evolution$q$, $q$What is natural selection?$q$, $q${"A":"A deliberate human breeding programme","B":"Differential survival and reproduction of inherited variants","C":"A change in one organism because it tries harder","D":"Formation of all species in one day"}$q$::jsonb, $q$B$q$, $q$Heritable traits affecting reproductive success can become more common over generations.$q$),
  ($q$Evolution$q$, $q$Why are fossils useful in studying evolution?$q$, $q${"A":"They prove no species changed","B":"They contain every organism that ever lived","C":"They preserve evidence of past organisms and change over time","D":"They directly show every gene sequence"}$q$::jsonb, $q$C$q$, $q$Fossils provide a historical record, though incomplete, of earlier life forms.$q$),
  ($q$Evolution$q$, $q$Two species have similar forelimb bone patterns used for different tasks. What may this indicate?$q$, $q${"A":"No relationship is possible","B":"Identical lifestyles","C":"They are the same species","D":"Common ancestry with modified functions"}$q$::jsonb, $q$D$q$, $q$Homologous structures can reflect inherited anatomy adapted to different uses.$q$),
  ($q$Evolution$q$, $q$Why must useful variation be heritable for natural selection to change a population over generations?$q$, $q${"A":"Only inherited differences can be passed to offspring","B":"All acquired changes alter genes","C":"Selection occurs only in one lifespan","D":"Mutation is impossible"}$q$::jsonb, $q$A$q$, $q$Traits that are not transmitted cannot increase in frequency through reproduction.$q$),
  ($q$Evolution$q$, $q$A population of insects contains some resistant individuals before pesticide use. What happens after repeated treatment?$q$, $q${"A":"All insects become identical immediately","B":"Resistant individuals may make up a larger fraction","C":"No insect can reproduce","D":"Every insect chooses to change its genes"}$q$::jsonb, $q$B$q$, $q$Survival and reproduction favour pre-existing heritable resistance.$q$),
  ($q$Evolution$q$, $q$What is an adaptation?$q$, $q${"A":"Any injury acquired in life","B":"Only a voluntary action","C":"A heritable trait that improves survival or reproduction in an environment","D":"A property that always helps in every habitat"}$q$::jsonb, $q$C$q$, $q$Adaptations increase fitness in particular environmental conditions.$q$),
  ($q$Evolution$q$, $q$Why do related species sometimes share similar DNA sequences?$q$, $q${"A":"They must live in the same town","B":"DNA is unrelated to ancestry","C":"All sequences are identical","D":"They inherited many sequences from a common ancestor"}$q$::jsonb, $q$D$q$, $q$Shared ancestry preserves parts of genetic sequence even as species diverge.$q$),
  -- Adaptation and survival (8)
  ($q$Adaptation and Survival$q$, $q$Why do some desert plants open stomata mainly at night?$q$, $q${"A":"Cooler night air reduces water loss","B":"They never need carbon dioxide","C":"Photosynthesis occurs only without light","D":"Stomata have no effect on evaporation"}$q$::jsonb, $q$A$q$, $q$Night opening allows CO₂ uptake with less evaporative loss; carbon can be stored for daytime use.$q$),
  ($q$Adaptation and Survival$q$, $q$How does thick fur benefit a mammal in a cold climate?$q$, $q${"A":"It creates heat from nothing","B":"It traps air and reduces heat transfer","C":"It prevents breathing","D":"It removes blood vessels"}$q$::jsonb, $q$B$q$, $q$Trapped still air acts as insulation against heat loss.$q$),
  ($q$Adaptation and Survival$q$, $q$Why can social insects work efficiently as a colony?$q$, $q${"A":"Every insect performs every task alone","B":"They have no communication","C":"Different members specialize and coordinate tasks","D":"Colonies never need food"}$q$::jsonb, $q$C$q$, $q$Division of labour among workers, reproductives and defenders helps colony functioning.$q$),
  ($q$Adaptation and Survival$q$, $q$What advantage does camouflage give a prey animal?$q$, $q${"A":"It guarantees immortality","B":"It makes it larger","C":"It increases all predator vision","D":"It can reduce detection by predators"}$q$::jsonb, $q$D$q$, $q$Colour and pattern matching the environment make prey harder to notice.$q$),
  ($q$Adaptation and Survival$q$, $q$Why are streamlined bodies useful to fast-swimming fish?$q$, $q${"A":"They reduce water resistance","B":"They eliminate oxygen needs","C":"They make fins unnecessary","D":"They increase drag deliberately"}$q$::jsonb, $q$A$q$, $q$A streamlined shape reduces drag during movement through water.$q$),
  ($q$Adaptation and Survival$q$, $q$Why do many insect-pollinated flowers produce scent and nectar?$q$, $q${"A":"To make seeds heavier","B":"To attract pollinators that transfer pollen","C":"To stop fertilization","D":"To replace roots"}$q$::jsonb, $q$B$q$, $q$Rewards and cues draw insects that carry pollen between flowers.$q$),
  ($q$Adaptation and Survival$q$, $q$What advantage do spines give a cactus besides reducing leaf surface area?$q$, $q${"A":"They create rain","B":"They directly pump water","C":"They can deter herbivores","D":"They replace photosynthetic tissue entirely"}$q$::jsonb, $q$C$q$, $q$Spines discourage animals from eating water-rich tissues.$q$),
  ($q$Adaptation and Survival$q$, $q$How does a waxy waterproof feather layer help water birds?$q$, $q${"A":"It stops all flight","B":"It replaces the lungs","C":"It stores all food","D":"It helps keep plumage dry and insulating"}$q$::jsonb, $q$D$q$, $q$Water-resistant feathers retain air and reduce waterlogging.$q$),
  -- Nigeria-relevant theory and applied biology (8)
  ($q$Applied Biology and Health$q$, $q$Why is nitrification useful in a cultivated soil?$q$, $q${"A":"Bacteria convert ammonium into nitrate plants can absorb","B":"It turns all nitrate into oxygen","C":"It stops the nitrogen cycle","D":"It makes soil sterile"}$q$::jsonb, $q$A$q$, $q$Nitrifying bacteria oxidize ammonium through nitrite to nitrate.$q$),
  ($q$Applied Biology and Health$q$, $q$What problem can kidney stones cause when they block urinary flow?$q$, $q${"A":"Improved filtration automatically","B":"Pain and obstruction of urine movement","C":"Production of more red cells only","D":"Better gas exchange"}$q$::jsonb, $q$B$q$, $q$A stone can obstruct the urinary tract and cause significant pain.$q$),
  ($q$Applied Biology and Health$q$, $q$Why is clean water especially important when controlling cholera outbreaks?$q$, $q${"A":"Cholera spreads by sunlight","B":"Only mosquitoes carry cholera","C":"Contaminated water can carry the causative bacterium","D":"The disease cannot spread between communities"}$q$::jsonb, $q$C$q$, $q$Cholera commonly spreads through water or food contaminated with Vibrio cholerae.$q$),
  ($q$Applied Biology and Health$q$, $q$What does a seed embryo need to begin normal germination besides a suitable temperature and oxygen?$q$, $q${"A":"A pollinator","B":"A mature leaf","C":"A fruit still attached","D":"Water"}$q$::jsonb, $q$D$q$, $q$Water activates enzymes and allows metabolic reactions in the seed.$q$),
  ($q$Applied Biology and Health$q$, $q$Why should fish catches be limited when stocks are declining?$q$, $q${"A":"To leave enough breeders for population recovery","B":"To make fish grow without food","C":"To eliminate aquatic plants","D":"To prevent all natural deaths"}$q$::jsonb, $q$A$q$, $q$Reduced harvesting can help breeding adults replenish the population.$q$),
  ($q$Applied Biology and Health$q$, $q$What is a role of microorganisms in wastewater treatment?$q$, $q${"A":"They create sewage","B":"They break down organic waste","C":"They prevent all aeration","D":"They turn pathogens into nutrients automatically"}$q$::jsonb, $q$B$q$, $q$Microbial communities digest organic material, reducing waste load.$q$),
  ($q$Applied Biology and Health$q$, $q$Why is prenatal care important during pregnancy?$q$, $q${"A":"It guarantees no complications","B":"It replaces nutrition","C":"It can detect and manage health risks early","D":"It determines a child's exam score"}$q$::jsonb, $q$C$q$, $q$Regular care monitors maternal and fetal health and supports timely intervention.$q$),
  ($q$Applied Biology and Health$q$, $q$What does a food web show that a single food chain often omits?$q$, $q${"A":"Only one feeding route","B":"Only producers","C":"Only one predator","D":"Interconnected feeding relationships"}$q$::jsonb, $q$D$q$, $q$A food web links multiple chains and possible energy pathways.$q$)
)
insert into public.questions (subject_id, exam_type, source, year, topic, prompt, options, correct_answer, explanation)
select subject.id, subject.exam_type, $q$original$q$, null,
       candidate.topic, candidate.prompt, candidate.options, candidate.correct_answer, candidate.explanation
from candidates as candidate
cross join public.subjects as subject
where subject.id = '7669b317-a1e1-45bc-aa18-51bae3b24b1d'::uuid
  and lower(subject.exam_type::text) = 'waec'
  and not exists (select 1 from public.questions as existing where existing.subject_id = subject.id and existing.prompt = candidate.prompt);
commit;
